python3 -c "import sys; sys.path.insert(0, '.'); from app.payments import call_with_retries, TransientError; calls={'n': 0}
def flaky(attempt):
    calls['n'] += 1
    if calls['n'] < 3:
        raise TransientError('transient')
    return {'ok': True, 'attempt': attempt}
r = call_with_retries(flaky, 3)
assert r == {'ok': True, 'attempt': 3}, r
assert calls['n'] == 3, calls['n']"
